class Q{String s(boolean p,String[]l){int w=l[0].length(),n=w*l.length,a=p?1:4,b=p?3:10;long v[]=new long[n*5],r=1-n;var q=new java.util.ArrayDeque();v[4]=-1;for(q.add(4);q.size()>0;){int s=(int)q.poll(),d=s%5,o=s/5;long c=~v[s];for(int t=4;t-->0;)if(d>3|t%2!=d%2){long C=c;for(int i=0;i++<b;){int O=o+i*(t%2<1?1-t:(2-t)*w);if(O<0|O>=n|t%2<1&O/w!=o/w)break;C+=l[O/w].charAt(O%w)-48;s=O*5+t;if(i>=a&(v[s]==0|C<~v[s])){v[s]=~C;q.add(s);if(O==n-1&(r<0|C<r))r=C;}}}}return r<0?"":r+"";}}
